-- =====================================================================
--  Deux lectures : Hafs et Warsh.
--  Chaque élève choisit la sienne (à la première connexion, modifiable ensuite,
--  y compris par son Cheikh). Les passages sont enregistrés dans la numérotation
--  de sa lecture ; changer de lecture convertit ses passages.
--
--  Sources : données du Complexe du Roi Fahd (KFGQPC) — Warsh v10 (6214 versets),
--  Hafs v18 (6236 versets). Correspondance verset à verset obtenue en alignant
--  les deux textes mot à mot (un verset peut correspondre à deux de l'autre lecture).
-- =====================================================================

create type public.lecture as enum ('hafs', 'warsh');

-- null : pas encore choisie (la lecture Hafs s'applique en attendant).
alter table public.profils add column lecture public.lecture;

