alter table public.sourates
  alter column nb_versets_warsh set not null,
  alter column premier_verset_global_warsh set not null;

-- Correspondance Hafs ↔ Warsh : chaque ligne relie deux versets qui partagent du texte.
create table public.correspondance_versets (
  sourate       smallint not null references public.sourates(numero),
  verset_hafs   smallint not null check (verset_hafs > 0),
  verset_warsh  smallint not null check (verset_warsh > 0),
  primary key (sourate, verset_hafs, verset_warsh)
);
create index on public.correspondance_versets (sourate, verset_warsh);
alter table public.correspondance_versets enable row level security;
create policy correspondance_lecture on public.correspondance_versets
  for select to authenticated using (true);
revoke insert, update, delete on public.correspondance_versets from anon, authenticated;


-- ---------- Outils -------------------------------------------------------

-- Lecture d'un élève (Hafs tant qu'il n'a pas choisi).
create or replace function public.lecture_de(p_eleve uuid) returns public.lecture
language sql stable set search_path = public as $$
  select coalesce((select lecture from profils where id = p_eleve), 'hafs'::lecture)
$$;

-- Nombre de versets et index global du verset 1 d'une sourate, selon la lecture.
create or replace function public.nb_versets_de(p_sourate smallint, p_lecture public.lecture) returns smallint
language sql stable set search_path = public as $$
  select case p_lecture when 'warsh' then nb_versets_warsh else nb_versets end from sourates where numero = p_sourate
$$;
create or replace function public.premier_global_de(p_sourate smallint, p_lecture public.lecture) returns integer
language sql stable set search_path = public as $$
  select case p_lecture when 'warsh' then premier_verset_global_warsh else premier_verset_global end
    from sourates where numero = p_sourate
$$;

-- ---------- Versets dans les bornes de la sourate, selon la lecture de l'élève ----------
create or replace function public.verifier_versets() returns trigger
language plpgsql set search_path = public as $$
declare
  v_lecture lecture := lecture_de((select eleve_id from seances where id = new.seance_id));
begin
  if new.verset_debut > nb_versets_de(new.sourate_debut, v_lecture)
  or new.verset_fin   > nb_versets_de(new.sourate_fin, v_lecture) then
    raise exception 'Verset hors de la sourate' using errcode = 'check_violation';
  end if;
  return new;
end $$;

-- ---------- La lecture ne change que par changer_lecture (qui convertit les passages) ----------
create or replace function public.proteger_profil() returns trigger
language plpgsql set search_path = public as $$
begin
  if auth.uid() is not null and not est_admin() then
    if new.role is distinct from old.role
       or new.etablissement_id is distinct from old.etablissement_id then
      raise exception 'Modification réservée à l''administrateur' using errcode = 'insufficient_privilege';
    end if;
    -- un maître peut (dés)activer ses élèves, pas lui-même ni un autre maître
    if new.actif is distinct from old.actif and not est_maitre_de(old.id) then
      raise exception 'Modification réservée à l''administrateur' using errcode = 'insufficient_privilege';
    end if;
  end if;
  if new.lecture is distinct from old.lecture
     and coalesce(current_setting('app.conversion_lecture', true), '') <> 'oui' then
    raise exception 'La lecture se change avec changer_lecture' using errcode = 'insufficient_privilege';
  end if;
  return new;
end $$;

-- ---------- Pendant une conversion, la marque « vu par le Cheikh » est conservée ----------
create or replace function public.marquer_correction_passage() returns trigger
language plpgsql set search_path = public as $$
declare
  v_eleve uuid := (select eleve_id from seances where id = new.seance_id);
begin
  if coalesce(current_setting('app.suppression_en_cours', true), '') = 'oui' then
    return new;
  end if;
  if tg_op = 'UPDATE' and coalesce(current_setting('app.conversion_lecture', true), '') = 'oui' then
    -- même passage, autre numérotation : ce que le Cheikh a vu reste vu
    new.corrige_par := old.corrige_par;
    new.corrige_le  := old.corrige_le;
    return new;
  end if;
  if auth.uid() is not null and auth.uid() is distinct from v_eleve then
    -- un encadrant enregistre : il a vu ce passage
    new.corrige_par := auth.uid();
    new.corrige_le  := now();
  elsif tg_op = 'INSERT'
     or (new.sourate_debut, new.verset_debut, new.sourate_fin, new.verset_fin)
        is distinct from (old.sourate_debut, old.verset_debut, old.sourate_fin, old.verset_fin) then
    -- l'élève ajoute ou change un passage : pas encore vu
    new.corrige_par := null;
    new.corrige_le  := null;
  else
    -- l'élève réordonne seulement : la marque ne bouge pas (et ne peut pas être forgée)
    new.corrige_par := old.corrige_par;
    new.corrige_le  := old.corrige_le;
  end if;
  return new;
end $$;

-- ---------- Un verset dans la numérotation de l'autre lecture ----------
-- Début d'un passage : premier verset correspondant ; fin : dernier verset correspondant.
-- La basmala (verset 1 de la Fatiha en Hafs) n'est pas comptée en Warsh : on prend le verset voisin.
create or replace function public.convertir_verset(
  p_sourate smallint, p_verset smallint, p_vers public.lecture, p_debut boolean
) returns smallint
language sql stable set search_path = public as $$
  select coalesce(
    case
      when p_vers = 'warsh' and p_debut then
        (select min(verset_warsh) from correspondance_versets
          where sourate = p_sourate
            and verset_hafs = (select min(verset_hafs) from correspondance_versets
                                where sourate = p_sourate and verset_hafs >= p_verset))
      when p_vers = 'warsh' then
        (select max(verset_warsh) from correspondance_versets
          where sourate = p_sourate
            and verset_hafs = (select max(verset_hafs) from correspondance_versets
                                where sourate = p_sourate and verset_hafs <= p_verset))
      when p_debut then
        (select min(verset_hafs) from correspondance_versets where sourate = p_sourate and verset_warsh = p_verset)
      else
        (select max(verset_hafs) from correspondance_versets where sourate = p_sourate and verset_warsh = p_verset)
    end,
    -- verset inconnu de la correspondance (ne devrait pas arriver) : borne de la sourate
    case when p_debut then 1::smallint else nb_versets_de(p_sourate, p_vers) end
  )::smallint
$$;

-- ---------- Changer de lecture : l'élève lui-même, son Cheikh ou l'admin ----------
-- Les passages déjà saisis passent dans la numérotation de la nouvelle lecture :
-- début = premier verset correspondant, fin = dernier verset correspondant.
-- (La basmala, verset 1 de la Fatiha en Hafs, n'est pas comptée en Warsh.)
create or replace function public.changer_lecture(p_eleve uuid, p_lecture public.lecture) returns void
language plpgsql
security invoker            -- les droits restent ceux des règles d'accès (RLS)
set search_path = public
as $$
declare
  v_avant lecture;
begin
  if p_lecture is null then
    raise exception 'Lecture manquante' using errcode = 'invalid_parameter_value';
  end if;
  if not exists (select 1 from profils where id = p_eleve and role = 'eleve') or not peut_acceder(p_eleve) then
    raise exception 'Élève introuvable' using errcode = 'insufficient_privilege';
  end if;
  v_avant := lecture_de(p_eleve);
  perform set_config('app.conversion_lecture', 'oui', true);

  update profils set lecture = p_lecture where id = p_eleve;
  if not found then
    raise exception 'Élève introuvable' using errcode = 'insufficient_privilege';
  end if;

  if v_avant <> p_lecture then
    update passages p
       set verset_debut = convertir_verset(p.sourate_debut, p.verset_debut, p_lecture, true),
           verset_fin   = convertir_verset(p.sourate_fin, p.verset_fin, p_lecture, false)
      from seances s
     where s.id = p.seance_id and s.eleve_id = p_eleve;
  end if;

  perform set_config('app.conversion_lecture', '', true);
end $$;
revoke all on function public.changer_lecture(uuid, public.lecture) from public, anon;
grant execute on function public.changer_lecture(uuid, public.lecture) to authenticated;

-- ---------- Enregistrement : chevauchements comptés dans la numérotation de la lecture de l'élève ----------
create or replace function public.enregistrer_seance(
  p_date      date,
  p_type      public.type_seance,
  p_duree     smallint,
  p_tajwid    text,
  p_note      text,
  p_passages  jsonb,
  p_eleve     uuid default auth.uid()
) returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id uuid;
  v_lecture lecture := lecture_de(p_eleve);
begin
  if jsonb_typeof(coalesce(p_passages, '[]'::jsonb)) <> 'array' then
    raise exception 'Passages invalides' using errcode = 'invalid_parameter_value';
  end if;
  if jsonb_array_length(coalesce(p_passages, '[]'::jsonb)) > 20 then
    raise exception 'Trop de passages (20 au maximum)' using errcode = 'invalid_parameter_value';
  end if;

  -- Deux passages d'une même séance ne se chevauchent pas.
  if exists (
    select 1
      from passages_entree(p_passages) a
      join passages_entree(p_passages) b on a.ordre < b.ordre
     where premier_global_de(a.sd, v_lecture) + a.vd - 1 <= premier_global_de(b.sf, v_lecture) + b.vf - 1
       and premier_global_de(b.sd, v_lecture) + b.vd - 1 <= premier_global_de(a.sf, v_lecture) + a.vf - 1
  ) then
    raise exception 'Deux passages se chevauchent' using errcode = 'check_violation';
  end if;

  values (p_eleve, p_date, p_type, p_duree, nullif(trim(p_tajwid), ''), nullif(trim(p_note), ''))
  on conflict (eleve_id, date, type) do update
    set duree_min  = excluded.duree_min,
        tajwid     = excluded.tajwid,
        note_libre = excluded.note_libre
  returning id into v_id;

  -- 1. Passages retirés ou modifiés : supprimés.
  delete from passages x
   where x.seance_id = v_id
     and not exists (select 1 from passages_entree(p_passages) e
                      where (e.sd, e.vd, e.sf, e.vf) = (x.sourate_debut, x.verset_debut, x.sourate_fin, x.verset_fin));

  -- 2. Passages inchangés : conservés (l'ordre est mis à jour ; un encadrant les marque vus).
  update passages x
     set ordre = e.ordre
    from passages_entree(p_passages) e
   where x.seance_id = v_id
     and (e.sd, e.vd, e.sf, e.vf) = (x.sourate_debut, x.verset_debut, x.sourate_fin, x.verset_fin)
     and (x.ordre is distinct from e.ordre or auth.uid() is distinct from p_eleve);

  -- 3. Nouveaux passages.
  select v_id, e.ordre, e.sd, e.vd, e.sf, e.vf
    from passages_entree(p_passages) e
   where not exists (select 1 from passages x
                      where x.seance_id = v_id
                        and (e.sd, e.vd, e.sf, e.vf) = (x.sourate_debut, x.verset_debut, x.sourate_fin, x.verset_fin));

  return v_id;
end $$;

revoke all on function public.enregistrer_seance(date, public.type_seance, smallint, text, text, jsonb, uuid) from public, anon;
grant execute on function public.enregistrer_seance(date, public.type_seance, smallint, text, text, jsonb, uuid) to authenticated;
